SQL_DOC.P_SQL:
SELECT '$G_RS.IF_ORDR_NO$' AS LEGACY_PO_NO , $G_RS.IF_ORDR_SEQ$ AS LEGACY_PO_SEQ , F_GET_ORDER_TRACKING('$G_RS.CSTMR_ID$','$G_RS.ORDR_NO$', $G_RS.ORDR_SEQ$ ,'STATUS') AS STATUS FROM DUAL
DECLARE BEGIN
CASE '$G_RS.DOC_NAME$' WHEN '01_PO' THEN UPDATE KEPMPSO06 SO06 SET SND_CHK = 'Y' , SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND ORDR_NO = '$G_RS.KEY_1$' AND ORDR_SEQ= $G_RS.KEY_2$; WHEN '02_RS' THEN UPDATE KEPMPRS02 SET SND_CHK = 'Y' , SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND DLVRY_PLAN_NO = '$G_RS.KEY_1$' AND DLVRY_PLAN_SEQ= $G_RS.KEY_2$; WHEN '03_IV' THEN IF '$G_RS.IS_HEAD$' = 'Y' THEN UPDATE KEPMPSV01 SET SND_CHK = 'Y' , SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND DEAL_STTMN_NO = '$G_RS.KEY_1$'; END IF; UPDATE KEPMPSV02 SET SND_CHK = 'Y' , SND_DATM= SYSDATE WHERE DEAL_STTMN_NO = '$G_RS.KEY_1$' AND DEAL_STTMN_SEQ= $G_RS.KEY_2$; WHEN '04_DI' THEN UPDATE KEPWMDE02 DE02 SET SND_CHK = 'Y' , SND_DATM=SYSDATE WHERE SHP_NO = '$G_RS.KEY_1$' AND SHP_SEQ= $G_RS.KEY_2$; WHEN '05_GR' THEN UPDATE KEPMPGR02 SET SND_CHK = 'Y' , SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND CSTMR_STCKAG_NO = '$G_RS.KEY_1$' AND CSTMR_STCKAG_SEQ = $G_RS.KEY_2$ AND SND_CHK = 'N'; ELSE NULL; END CASE;
END;
DECLARE BEGIN
CASE '$G_RS.DOC_NAME$' WHEN '01_PO' THEN UPDATE KEPMPSO06 SO06 SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND ORDR_NO = '$G_RS.KEY_1$' AND ORDR_SEQ= $G_RS.KEY_2$; WHEN '02_RS' THEN UPDATE KEPMPRS02 SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND DLVRY_PLAN_NO = '$G_RS.KEY_1$' AND DLVRY_PLAN_SEQ= $G_RS.KEY_2$; WHEN '03_IV' THEN IF '$G_RS.IS_HEAD$' = 'Y' THEN UPDATE KEPMPSV01 SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND DEAL_STTMN_NO = '$G_RS.KEY_1$'; END IF; UPDATE KEPMPSV02 SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE DEAL_STTMN_NO = '$G_RS.KEY_1$' AND DEAL_STTMN_SEQ= $G_RS.KEY_2$; WHEN '04_DI' THEN UPDATE KEPWMDE02 DE02 SET SND_CHK = 'E' ,SND_DATM=SYSDATE WHERE SHP_NO = '$G_RS.KEY_1$' AND SHP_SEQ= $G_RS.KEY_2$; WHEN '05_GR' THEN UPDATE KEPMPGR02 SET SND_CHK = 'E' ,SND_DATM= SYSDATE WHERE CSTMR_ID = '$G_RS.CSTMR_ID$' AND CSTMR_STCKAG_NO = '$G_RS.KEY_1$' AND CSTMR_STCKAG_SEQ= $G_RS.KEY_2$; ELSE NULL; END CASE; END;
